import {
  SchemaDocument,
  TypeDefinition,
  TypeNode,
} from '../ir/types';

export interface KotlinGeneratorOptions {
  packageName?: string;
}

/**
 * Generates idiomatic Kotlin data classes and enums using kotlinx.serialization.
 */
export function generateKotlin(
  doc: SchemaDocument,
  options: KotlinGeneratorOptions = { packageName: 'com.example.models' }
): string {
  const lines: string[] = [
    '// Code generated by TypeBridge. DO NOT EDIT.',
    `package ${options.packageName || 'com.example.models'}`,
    '',
    'import kotlinx.serialization.SerialName',
    'import kotlinx.serialization.Serializable',
    '',
  ];

  for (const def of doc.definitions) {
    if (def.kind === 'struct') {
      lines.push(generateKotlinClass(def));
      lines.push('');
    } else if (def.kind === 'enum') {
      lines.push(generateKotlinEnum(def));
      lines.push('');
    } else if (def.kind === 'alias') {
      lines.push(`typealias ${def.name} = ${mapTypeToKotlin(def.targetType)}`);
      lines.push('');
    }
  }

  return lines.join('\n');
}

function generateKotlinClass(def: Extract<TypeDefinition, { kind: 'struct' }>): string {
  const lines: string[] = [];
  if (def.description) {
    lines.push(`/** ${def.description} */`);
  }
  lines.push('@Serializable');

  if (def.fields.length === 0) {
    lines.push(`class ${def.name}`);
    return lines.join('\n');
  }

  lines.push(`data class ${def.name}(`);

  def.fields.forEach((field, idx) => {
    const ktName = toCamelCase(field.name);
    const ktType = mapTypeToKotlin(field.type);
    const comma = idx < def.fields.length - 1 ? ',' : '';

    if (field.description) {
      lines.push(`    /** ${field.description} */`);
    }
    if (field.deprecated) {
      lines.push('    @Deprecated("Deprecated in schema")');
    }
    if (ktName !== field.name) {
      lines.push(`    @SerialName("${field.name}")`);
    }

    if (field.optional) {
      lines.push(`    val ${ktName}: ${ktType}? = null${comma}`);
    } else {
      lines.push(`    val ${ktName}: ${ktType}${comma}`);
    }
  });

  lines.push(')');
  return lines.join('\n');
}

function generateKotlinEnum(def: Extract<TypeDefinition, { kind: 'enum' }>): string {
  const lines: string[] = [];
  if (def.description) {
    lines.push(`/** ${def.description} */`);
  }
  lines.push('@Serializable');
  lines.push(`enum class ${def.name} {`);

  def.values.forEach((val, idx) => {
    const safeName = val.name.toUpperCase().replace(/[^A-Z0-9_]/g, '_');
    const comma = idx < def.values.length - 1 ? ',' : '';
    lines.push(`    @SerialName("${val.value}")`);
    lines.push(`    ${safeName}${comma}`);
  });

  lines.push('}');
  return lines.join('\n');
}

function mapTypeToKotlin(node: TypeNode): string {
  switch (node.kind) {
    case 'primitive':
      switch (node.primitive) {
        case 'string':
        case 'date':
        case 'uuid':
          return 'String';
        case 'number':
          return 'Double';
        case 'integer':
          return 'Long';
        case 'boolean':
          return 'Boolean';
        case 'null':
        case 'any':
        default:
          return 'Any';
      }
    case 'reference':
      return node.name;
    case 'array':
      return `List<${mapTypeToKotlin(node.elementType)}>`;
    case 'map':
      return `Map<${mapTypeToKotlin(node.keyType)}, ${mapTypeToKotlin(node.valueType)}>`;
    case 'optional':
      return `${mapTypeToKotlin(node.innerType)}?`;
    case 'union':
      return 'Any';
    case 'literal':
      return typeof node.value === 'string' ? 'String' : typeof node.value === 'number' ? 'Double' : 'Boolean';
    default:
      return 'Any';
  }
}

function toCamelCase(str: string): string {
  return str.replace(/[-_](\w)/g, (_, c) => c.toUpperCase());
}
